parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "mensagem": {
      "type": "string",
      "description": "Texto acolhedor e humanizado enviado pela Júlia para o WhatsApp do paciente."
    },
    "event_id": {
      "type": ["string", "null"],
      "description": "O identificador único do agendamento retornado pelo Google Calendar. Deve ser null se não houver agendamento confirmado."
    },
    "patient_name": {
      "type": ["string", "null"],
      "description": "Nome completo do paciente capturado. Deve ser null se não houver nome confirmado."
    },
    "dateTime": {
      "type": ["string", "null"],
      "description": "Data e horário da consulta no formato brasileiro. Deve ser null se não houver agendamento confirmado."
    }
  },
  "required": ["mensagem", "event_id", "patient_name", "dateTime"]
}
